#nullable enable // autogenerated

using MVZ2.GameContent.Enemies;
using MVZ2.Vanilla.Enemies;
using MVZ2.Vanilla.Entities;
using MVZ2.Vanilla.Modifiers;
using MVZ2.Vanilla.Properties;
using PVZEngine.Buffs;
using PVZEngine.Entities;
using PVZEngine.Level;
using PVZEngine.Modifiers;

namespace MVZ2.GameContent.Buffs.Enemies
{
    [BuffDefinition(VanillaBuffNames.Enemy.flyingPirateGlide)]
    public class FlyingPirateGlideBuff : BuffDefinition
    {
        public FlyingPirateGlideBuff(string nsp, string name) : base(nsp, name)
        {
            AddModifier(new FloatModifier(EngineEntityProps.GRAVITY, NumberOperator.Multiply, 0));
            AddModifier(new FloatModifier(VanillaEnemyProps.SPEED, NumberOperator.Set, 10, VanillaModifierPriorities.FORCE));
            AddModifier(new IntModifier(VanillaEnemyProps.STATE_OVERRIDE, IntegerOperator.Set, VanillaEnemyStates.IDLE));
        }
        public override void PostAdd(Buff buff)
        {
            base.PostAdd(buff);
            var entity = buff.GetEntity();
            if (entity == null)
                return;
            entity.SetAnimationBool("Parachuting", true);
        }
        public override void PostRemove(Buff buff)
        {
            base.PostRemove(buff);
            var entity = buff.GetEntity();
            if (entity == null)
                return;
            entity.SetAnimationBool("Parachuting", IsParachuting(entity));
            entity.RemoveBuffs<FlyBuff>();
        }
        public override void PostUpdate(Buff buff)
        {
            base.PostUpdate(buff);
            var entity = buff.GetEntity();
            if (entity == null)
                return;
            if (entity.Definition.GetID() != VanillaEnemyID.flyingPirate)
            {
                buff.Remove();
                return;
            }

            bool paragliderDiscard = entity.GetProperty<bool>(FlyingPirate.PROP_PARAGLIDER_DISCARDED);
            if (paragliderDiscard)
            {
                buff.Remove();
                return;
            }

            var col = buff.GetProperty<int>(PROP_TARGET_COLUMN);
            if (entity.IsTimeInterval(5, 3) && ((entity.GetColumn() - col) * entity.GetFacingX() >= 0 || entity.IsOnGround || entity.IsAIFrozen()))
            {
                buff.Remove();
            }
        }
        public static bool IsParachuting(Entity entity)
        {
            return entity.HasBuff<FlyingPirateGlideBuff>();
        }
        public static readonly VanillaBuffPropertyMeta<float> PROP_SPEED = new VanillaBuffPropertyMeta<float>("Speed", 1);
        public static readonly VanillaBuffPropertyMeta<int> PROP_TARGET_COLUMN = new VanillaBuffPropertyMeta<int>("target_column", 4);
    }
}
